/**
 * @event
 * @name scwin.rowPlus_oncellclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.rowPlus_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_lecrDiptSchdl');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_lecrDiptSchdl'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.inRows === 'function') { scwin.inRows(); } else { console.error('[sdd] 행 동작 미정의: scwin.inRows (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.inRows'); } return;
        if (typeof scwin.delRows === 'function') { await scwin.delRows(); } else { console.error('[sdd] 행 동작 미정의: scwin.delRows (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.delRows'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'rowPlus.oncellclick' });
    }
};

